import { HttpClient } from "@angular/common/http";
import { DestroyRef, Injectable, inject, signal } from "@angular/core";
import { Router } from "@angular/router";
import { firstValueFrom } from "rxjs";
import { environment } from "../../../environments/environment";
import { PERMISOS_POR_ROL } from "../config/permisos";
import { LoginResponse, Permiso, Session } from "./auth.model";
const API_URL = environment.apiUrl;
@Injectable({ providedIn: "root" })
export class AuthService {
  private http = inject(HttpClient);
  private router = inject(Router);
  private destroyRef = inject(DestroyRef);
  private timer?: ReturnType<typeof setTimeout>;
  private avisoTimer?: ReturnType<typeof setTimeout>;
  session = signal<Session | null>(this.read());
  porVencer = signal(false);
  constructor() {
    this.programarVencimiento();
    this.destroyRef.onDestroy(() => this.cancelarTemporizador());
  }
  private validar(value: unknown): Session | null {
    if (!value || typeof value !== "object") return null;
    const s = value as Partial<LoginResponse>;
    if (
      typeof s.token !== "string" ||
      typeof s.usuario !== "string" ||
      !s.usuario.trim() ||
      !Number.isInteger(s.idUsuario) ||
      Number(s.idUsuario) <= 0 ||
      !Object.hasOwn(PERMISOS_POR_ROL, s.rol ?? "")
    )
      return null;
    try {
      const parts = s.token.split(".");
      if (parts.length !== 3 || parts.some((part) => !part)) return null;
      const payload = JSON.parse(
        atob(parts[1].replace(/-/g, "+").replace(/_/g, "/")),
      );
      if (typeof payload.exp !== "number" || !Number.isFinite(payload.exp))
        return null;
      const expiraEn = payload.exp * 1000;
      if (!Number.isFinite(expiraEn) || expiraEn <= Date.now()) return null;
      return {
        token: s.token,
        usuario: s.usuario,
        rol: s.rol!,
        idUsuario: s.idUsuario!,
        expiraEn,
      };
    } catch {
      return null;
    }
  }
  private read(): Session | null {
    try {
      const session = this.validar(
        JSON.parse(sessionStorage.getItem("karely_session") || "null"),
      );
      if (!session) sessionStorage.removeItem("karely_session");
      return session;
    } catch {
      sessionStorage.removeItem("karely_session");
      return null;
    }
  }
  private cancelarTemporizador() {
    if (this.timer !== undefined) clearTimeout(this.timer);
    if (this.avisoTimer !== undefined) clearTimeout(this.avisoTimer);
    this.timer = undefined;
    this.avisoTimer = undefined;
  }
  private programarVencimiento() {
    this.cancelarTemporizador();
    this.porVencer.set(false);
    const session = this.session();
    if (!session) return;
    const restante = Math.max(session.expiraEn - Date.now(), 0);
    this.avisoTimer = setTimeout(
      () => this.porVencer.set(true),
      Math.max(restante - 60_000, 0),
    );
    this.timer = setTimeout(
      () => {
        if (session.expiraEn <= Date.now()) this.clear(true);
        else this.programarVencimiento();
      },
      Math.min(restante, 2147483647),
    );
  }
  estaAutenticado(): boolean {
    const session = this.session();
    if (!session) return false;
    if (session.expiraEn <= Date.now()) {
      this.clear(true);
      return false;
    }
    return true;
  }
  tienePermiso(permiso: Permiso): boolean {
    return (
      this.estaAutenticado() &&
      !!PERMISOS_POR_ROL[this.session()!.rol]?.includes(permiso)
    );
  }
  async login(username: string, password: string): Promise<Session> {
    const response = await firstValueFrom(
      this.http.post<LoginResponse>(API_URL + "/auth/login", {
        username,
        password,
      }),
    );
    const session = this.validar(response);
    if (!session)
      throw new Error(
        "La respuesta de inicio de sesión no contiene una sesión válida",
      );
    sessionStorage.setItem("karely_session", JSON.stringify(session));
    this.session.set(session);
    this.programarVencimiento();
    return session;
  }
  async logout() {
    try {
      await firstValueFrom(this.http.post(API_URL + "/auth/logout", {}));
    } catch {
    } finally {
      this.clear();
    }
  }
  limpiarSesionLocal() {
    this.cancelarTemporizador();
    sessionStorage.removeItem("karely_session");
    this.session.set(null);
    this.porVencer.set(false);
  }
  clear(expirada = false) {
    this.limpiarSesionLocal();
    void this.router.navigateByUrl(
      expirada ? "/login?sesionExpirada=1" : "/login",
    );
  }
}

import { HttpInterceptorFn } from "@angular/common/http";
import { inject } from "@angular/core";
import { AuthService } from "../auth/auth-service";
import { isApiRequest } from "./api-request";
export const authInterceptor: HttpInterceptorFn = (request, next) => {
  const session = inject(AuthService).session();
  return next(
    session && isApiRequest(request.url)
      ? request.clone({
          setHeaders: { Authorization: "Bearer " + session.token },
        })
      : request,
  );
};

import { environment } from "../../../environments/environment";
export function isApiRequest(url: string): boolean {
  const base = environment.apiUrl.replace(/\/$/, "");
  return (
    url === base || url.startsWith(base + "/") || url.startsWith(base + "?")
  );
}

import { HttpErrorResponse, HttpInterceptorFn } from "@angular/common/http";
import { inject } from "@angular/core";
import { catchError, throwError } from "rxjs";
import { AuthService } from "../auth/auth-service";
import { isApiRequest } from "./api-request";
export const errorInterceptor: HttpInterceptorFn = (request, next) => {
  const auth = inject(AuthService);
  return next(request).pipe(
    catchError((error: HttpErrorResponse) => {
      if (
        isApiRequest(request.url) &&
        error.status === 401 &&
        !request.url.endsWith("/auth/login")
      )
        auth.clear();
      return throwError(() => error);
    }),
  );
};

import type { FormGroup } from "@angular/forms";

const fieldLabels: Record<string, string> = {
  tipoDocumento: "Tipo de documento",
  numeroDocumento: "Número de documento",
  nombres: "Nombres",
  apellidos: "Apellidos",
  telefono: "Teléfono",
  correo: "Correo",
  direccion: "Dirección",
  estado: "Estado",
  fechaNacimiento: "Fecha de nacimiento",
  username: "Usuario",
  idRol: "Rol",
};

export function formErrorText(form: FormGroup): string {
  const messages = Object.entries(form.controls)
    .filter(([, control]) => control.invalid)
    .map(([field, control]) => {
      const label = fieldLabels[field] || field;
      if (control.hasError("required")) return `${label}: completa este campo`;
      if (control.hasError("email"))
        return `${label}: ingresa un correo válido`;
      if (control.hasError("maxlength"))
        return `${label}: máximo ${control.getError("maxlength").requiredLength} caracteres`;
      if (control.hasError("fechaFutura"))
        return `${label}: no puede ser futura`;
      return `${label}: revisa el valor ingresado`;
    });
  return messages[0] || "Revisa los datos del formulario.";
}

export function errorText(error: unknown): string {
  const value = error as {
    status?: number;
    error?: {
      error?: string;
      detail?: string;
      message?: string;
      validationErrors?: Record<string, string>;
    };
    message?: string;
  } | null;
  if (value?.status === 0)
    return "No se pudo conectar con el sistema. Revisa tu conexión e inténtalo de nuevo.";
  if (value?.status && value.status >= 500)
    return "No se pudo completar la operación. Inténtalo de nuevo en unos minutos.";
  const fields = value?.error?.validationErrors;
  if (fields && Object.keys(fields).length) {
    const message = Object.values(fields).find(
      (text) => typeof text === "string" && text.trim(),
    );
    return mensajeClaro(message || "Revisa los datos del formulario.");
  }
  const message =
    value?.error?.message ||
    value?.error?.detail ||
    value?.error?.error ||
    value?.message ||
    "No se pudo completar la operación.";
  if (value?.status === 403)
    return "Tu cuenta no tiene permiso para realizar esta acción.";
  if (value?.status === 401)
    return /credenciales|contraseña|password/i.test(message)
      ? "Usuario o contraseña incorrectos."
      : "Tu sesión no es válida. Vuelve a iniciar sesión.";
  return mensajeClaro(message);
}

function mensajeClaro(message: string): string {
  if (typeof message !== "string") return "No se pudo completar la operación.";
  let text = message
    .replace(/\u00c3\u00b3/g, "ó")
    .replace(/\u00c3\u00a1/g, "á")
    .replace(/\u00c3\u00a9/g, "é")
    .replace(/\u00c3\u00ad/g, "í")
    .replace(/\u00c3\u00ba/g, "ú")
    .replace(/\u00c3\u00b1/g, "ñ");
  text = text
    .split(/\r?\n/)[0]
    .replace(/^\s*ORA-20\d{3}:\s*/, "")
    .trim();
  if (
    /ORA-\d|SQL(?:Exception|STATE)|\bSELECT\b.+\bFROM\b|constraint|Http failure|https?:\/\/|\b(?:TypeError|NullPointerException|Bad Request|Internal Server Error|Unauthorized|Forbidden)\b/i.test(
      text,
    )
  )
    return "No se pudo completar la operación. Inténtalo de nuevo.";
  if (
    /must (?:not|be|match)|size must|length must|not a well-formed/i.test(text)
  )
    return "Revisa los datos ingresados y completa los campos obligatorios.";
  return text || "No se pudo completar la operación.";
}

import { Paginador } from "../../../../shared/components/paginador/paginador";
import { ChangeDetectorRef, Component, inject, OnInit } from "@angular/core";
import { FormsModule } from "@angular/forms";
import { ActivatedRoute } from "@angular/router";
import { firstValueFrom } from "rxjs";
import { errorText } from "../../../../core/utils/http-error";
import { FeatureNav } from "../../../../shared/components/feature-nav/feature-nav";
import { Doctor, DocumentoDoctor } from "../../models/doctores.model";
import { DoctorService } from "../../services/doctores-service";

@Component({
  standalone: true,
  imports: [Paginador,FormsModule, FeatureNav],
  template:"<div class=\"k-module k-doctores\">\n  <header class=\"k-module-header\">\n    <div>\n      <span class=\"k-eyebrow\">GESTIÓN CLÍNICA / PERSONAL MÉDICO</span>\n      <h1 class=\"k-title\">Documentación de doctores</h1>\n      <p class=\"k-subtitle\">\n        Revisa por separado el DNI y el título profesional.\n      </p>\n    </div>\n  </header>\n  <app-feature-nav feature=\"doctores\" />\n  @if(error){\n  <div class=\"k-error\" role=\"alert\">{{error}}</div>\n  } @if(exito){\n  <div class=\"k-success\" role=\"status\">{{exito}}</div>\n  }\n  <section class=\"k-panel\">\n    <label class=\"k-field\"\n      >Doctor<select\n        [(ngModel)]=\"selectedDoctor\"\n        (ngModelChange)=\"cargarDocumentos()\"\n        [disabled]=\"guardando\"\n      >\n        <option [ngValue]=\"0\">Selecciona un doctor</option>\n        @for(d of doctores;track d.idDoctor){\n        <option [ngValue]=\"d.idDoctor\">\n          {{d.nombres}} {{d.apellidos}} — {{d.estadoDocumentacion}}\n        </option>\n        }\n      </select></label\n    >\n  </section>\n  @if(guardadoPendiente){\n  <p class=\"k-info\" role=\"status\">Hay archivos pendientes de subir.</p>\n  } @if(!selectedDoctor){\n  <section class=\"k-panel documentos-vacio\">\n    <h2>Selecciona al doctor que vas a revisar</h2>\n    <p>\n      Verás su DNI y su título profesional por separado. Abre ambos archivos\n      antes de confirmar la revisión manual.\n    </p>\n  </section>\n  }@else{\n  <div class=\"documentos-grid\">\n    @for(tipo of tipos;track selectedDoctor + ':' + tipo){\n    <section class=\"k-panel documento-card\">\n      <h2>{{tipo === 'DNI' ? 'DNI' : 'Título profesional'}}</h2>\n      @if(doctorSeleccionado;as doctor){\n      <p class=\"documento-identidad\">\n        <strong>{{doctor.nombres}} {{doctor.apellidos}}</strong\n        ><br />{{doctor.tipoDocumento}} registrado: {{doctor.numeroDocumento}}\n      </p>\n      }\n      <div class=\"documento-upload\">\n        <label class=\"k-field\"\n          >Archivo PDF o imagen (máximo 10 MB)<input\n            type=\"file\"\n            accept=\"application/pdf,image/png,image/jpeg\"\n            [disabled]=\"guardando || !selectedDoctor\"\n            (change)=\"cambiarArchivo($event,tipo)\"\n        /></label>\n        @if(archivos[tipo];as archivo){\n        <p class=\"k-info\">Pendiente de subir: {{archivo.name}}</p>\n        }\n        <button\n          class=\"k-button\"\n          [disabled]=\"guardando || !selectedDoctor || !archivos[tipo]\"\n          (click)=\"subirDocumento(tipo)\"\n        >\n          Subir {{tipo === 'DNI' ? 'DNI' : 'título'}}\n        </button>\n      </div>\n      @if(ultimo(tipo);as d){\n      <div class=\"documento-version\">\n        <h3>Última versión</h3>\n        <p class=\"documento-archivo\">\n          <span>{{d.nombreArchivo}}</span>\n          <span class=\"k-status\">{{d.estado}}</span>\n        </p>\n        @if(d.motivoRechazo){\n        <p>{{d.motivoRechazo}}</p>\n        }\n        <button class=\"k-button k-button-secondary\" (click)=\"verDocumento(d)\">\n          Ver archivo\n        </button>\n        <label class=\"k-field\"\n          >Motivo de rechazo<input\n            [(ngModel)]=\"motivos[d.idDocumento]\"\n            [disabled]=\"guardando\" /></label\n        ><button\n          class=\"k-button k-button-secondary\"\n          [disabled]=\"guardando || !motivos[d.idDocumento]?.trim()\"\n          (click)=\"rechazarDocumento(d)\"\n        >\n          Rechazar documento\n        </button>\n        @if(tipo === 'DNI'){<label class=\"revision\"\n          ><input\n            type=\"checkbox\"\n            [(ngModel)]=\"dniConforme\"\n            [disabled]=\"guardando || !abiertos.has(d.idDocumento) || d.estado === 'RECHAZADO'\"\n          />\n          Comprobé que número y nombres coinciden con el doctor\n          registrado</label\n        >}@else{<label class=\"revision\"\n          ><input\n            type=\"checkbox\"\n            [(ngModel)]=\"tituloConforme\"\n            [disabled]=\"guardando || !abiertos.has(d.idDocumento) || d.estado === 'RECHAZADO'\"\n          />\n          Título pertenece al doctor y es conforme</label\n        >}\n      </div>\n      }@else{\n      <p class=\"k-info\">Todavía no se adjuntó este documento.</p>\n      }\n    </section>\n    }\n  </div>\n  <section class=\"k-panel\">\n    <p class=\"k-info\">\n      Abre cada última versión y confirma su conformidad antes de aprobar.\n    </p>\n    <button\n      class=\"k-button\"\n      [disabled]=\"guardando || !selectedDoctor || !puedeAprobar\"\n      (click)=\"aprobarDoctor()\"\n    >\n      Validar DNI y título\n    </button>\n  </section>\n  <section class=\"k-panel\">\n    <h2>Historial de documentos</h2>\n    <div class=\"k-table-wrap\">\n      <table class=\"k-table\">\n        <thead>\n          <tr>\n            <th>Versión</th>\n            <th>Tipo</th>\n            <th>Archivo</th>\n            <th>Estado</th>\n            <th>Motivo</th>\n            <th>Acciones</th>\n          </tr>\n        </thead>\n        <tbody>\n          @for(d of tabla.contenido();track d.idDocumento){\n          <tr>\n            <td>{{d.idDocumento}}</td>\n            <td>{{d.tipoDocumento}}</td>\n            <td>{{d.nombreArchivo}}</td>\n            <td>{{d.estado}}</td>\n            <td>{{d.motivoRechazo || '—'}}</td>\n            <td>\n              <button\n                class=\"k-button k-button-small k-button-secondary\"\n                (click)=\"verDocumento(d)\"\n              >\n                Ver archivo\n              </button>\n            </td>\n          </tr>\n          }@empty{\n          <tr>\n            <td colspan=\"6\" class=\"k-empty\">Sin documentos para mostrar.</td>\n          </tr>\n          }\n        </tbody>\n      </table>\n    </div>\n    <app-paginador #tabla [registros]=\"documentos\" />\n  </section>\n  }\n</div>\n",
  styles:[],
})
export class DoctorDocumentos implements OnInit {
  private readonly changeDetector = inject(ChangeDetectorRef);
  guardando = false;
  private readonly route = inject(ActivatedRoute, { optional: true });

  private doctoresService = inject(DoctorService);
  doctores: Doctor[] = [];
  documentos: DocumentoDoctor[] = [];
  error = "";
  exito = "";
  selectedDoctor = 0;
  readonly tipos = ["DNI", "TITULO"];
  archivos: Record<string, File | null> = {};
  motivos: Record<number, string> = {};
  dniConforme = false;
  tituloConforme = false;
  abiertos = new Set<number>();
  private carga = 0;
  resetRevision() {
    this.dniConforme = false;
    this.tituloConforme = false;
    this.abiertos.clear();
  }
  ultimo(tipo: string) {
    return this.documentos
      .filter((d) => d.tipoDocumento === tipo)
      .sort((a, b) => b.idDocumento - a.idDocumento)[0];
  }
  get puedeAprobar() {
    return (
      this.tipos.every((tipo) => {
        const d = this.ultimo(tipo);
        return (
          !!d &&
          ["PENDIENTE", "VALIDADO"].includes(d.estado) &&
          this.abiertos.has(d.idDocumento)
        );
      }) &&
      this.dniConforme &&
      this.tituloConforme
    );
  }
  async verDocumento(d: DocumentoDoctor) {
    const doctor = this.selectedDoctor;
    const ventana = window.open("", "_blank");
    try {
      const blob = await firstValueFrom(
        this.doctoresService.descargarDocumento(doctor, d.idDocumento),
      );
      if (this.selectedDoctor !== doctor) {
        ventana?.close();
        return;
      }
      const url = URL.createObjectURL(blob);
      if (ventana) {
        ventana.location.href = url;
        this.abiertos.add(d.idDocumento);
      }
      setTimeout(() => URL.revokeObjectURL(url), 60000);
    } catch (e) {
      ventana?.close();
      this.error = errorText(e);
    } finally {
      this.changeDetector.markForCheck();
    }
  }
  async rechazarDocumento(d: DocumentoDoctor) {
    if (this.guardando) return;
    const motivo = this.motivos[d.idDocumento]?.trim();
    if (!motivo) {
      this.error = "Escribe el motivo del rechazo";
      return;
    }
    this.guardando = true;
    this.error = "";
    this.exito = "";
    const doctor = this.selectedDoctor;
    this.resetRevision();
    try {
      await firstValueFrom(
        this.doctoresService.rechazarDocumento(doctor, d.idDocumento, motivo),
      );
      if (doctor === this.selectedDoctor) {
        this.exito = "Documento rechazado";
        await this.cargarDocumentos();
      }
      await this.cargar();
    } catch (e) {
      this.error = errorText(e);
    } finally {
      this.guardando = false;
      this.changeDetector.markForCheck();
    }
  }
  get doctorSeleccionado() {
    return this.doctores.find((d) => d.idDoctor === this.selectedDoctor);
  }
  get guardadoPendiente() {
    return Object.values(this.archivos).some(Boolean);
  }
  ngOnInit() {
    const id = Number(this.route?.snapshot.queryParamMap.get("doctor"));
    if (id > 0) this.selectedDoctor = id;
    void this.cargar();
    if (id > 0) void this.cargarDocumentos();
  }
  async cargar() {
    try {
      try {
        this.doctores = await firstValueFrom(this.doctoresService.listar());
      } catch (e) {
        this.error = errorText(e);
      }
    } finally {
      this.changeDetector.markForCheck();
    }
  }
  async cargarDocumentos(preservarRevision = false, preservarArchivos = false) {
    const carga = ++this.carga;
    if (!preservarRevision) this.resetRevision();
    if (!preservarArchivos && !preservarRevision) this.archivos = {};
    try {
      const doctor = this.selectedDoctor;
      this.documentos = [];
      if (!doctor) return;
      try {
        const documentos = await firstValueFrom(
          this.doctoresService.documentos(doctor),
        );
        if (this.selectedDoctor === doctor && carga === this.carga)
          this.documentos = documentos;
      } catch (e) {
        if (this.selectedDoctor === doctor && carga === this.carga)
          this.error = errorText(e);
      }
    } finally {
      this.changeDetector.markForCheck();
    }
  }
  cambiarArchivo(e: Event, tipo: string) {
    this.archivos[tipo] = (e.target as HTMLInputElement).files?.item(0) || null;
  }
  async subirDocumento(tipo: string) {
    if (this.guardando) return;
    const archivo = this.archivos[tipo];
    this.resetRevision();
    this.guardando = true;
    try {
      this.error = "";
      this.exito = "";
      if (!archivo || !this.selectedDoctor) return;
      if (archivo.size > 10 * 1024 * 1024) {
        this.error = "El archivo supera el máximo de 10 MB";
        return;
      }
      try {
        await firstValueFrom(
          this.doctoresService.subir(this.selectedDoctor, tipo, archivo),
        );
        this.exito = "Documento recibido";
        this.archivos[tipo] = null;
        await this.cargarDocumentos(false, true);
        await this.cargar();
      } catch (e) {
        this.error = errorText(e);
      }
    } finally {
      this.guardando = false;
      this.changeDetector.markForCheck();
    }
  }
  async aprobarDoctor() {
    if (this.guardando) return;
    this.guardando = true;
    try {
      this.error = "";
      this.exito = "";
      const doctor = this.selectedDoctor;
      if (!doctor) {
        this.error = "Selecciona un doctor";
        return;
      }
      await this.cargarDocumentos(true);
      if (this.error || this.selectedDoctor !== doctor) return;
      const faltantes = ["DNI", "TITULO"].filter((tipo) => {
        const ultimo = this.documentos
          .filter((d) => d.tipoDocumento === tipo)
          .sort((a, b) => Number(b.idDocumento) - Number(a.idDocumento))[0];
        return !ultimo || !["PENDIENTE", "VALIDADO"].includes(ultimo.estado);
      });
      if (faltantes.length) {
        this.error =
          "Adjunta un DNI y un título profesional vigentes antes de validar. Falta o fue rechazado: " +
          faltantes
            .map((tipo) => (tipo === "TITULO" ? "Título profesional" : tipo))
            .join(", ");
        return;
      }
      if (!this.puedeAprobar) {
        this.error =
          "Abre, revisa y confirma el DNI y el título antes de validar";
        return;
      }
      try {
        await firstValueFrom(
          this.doctoresService.validarDocumentacion(doctor, {
            dniConforme: this.dniConforme,
            tituloConforme: this.tituloConforme,
            idDni: this.ultimo("DNI")!.idDocumento,
            idTitulo: this.ultimo("TITULO")!.idDocumento,
          }),
        );
        this.exito = "Documentación validada";
        await this.cargar();
      } catch (e) {
        this.error = errorText(e);
      }
      if (!this.error && this.selectedDoctor === doctor)
        await this.cargarDocumentos();
    } finally {
      this.guardando = false;
      this.changeDetector.markForCheck();
    }
  }
}

import { Component, computed, input, output, signal } from "@angular/core";

@Component({
  selector: "app-paginador",
  standalone: true,
  template:"<nav aria-label=\"Paginación del listado\" [attr.aria-busy]=\"cargando()\">\n  <span class=\"paginador-resumen\"\n    >{{ desde() }}–{{ hasta() }} de {{ total() }} registros</span\n  >\n  <label\n    >Filas por página\n    <select\n      [value]=\"filas()\"\n      (change)=\"cambiarTamanio($event)\"\n      [disabled]=\"cargando()\"\n    >\n      @for (cantidad of [10, 20, 50, 100]; track cantidad) {\n      <option [value]=\"cantidad\">{{ cantidad }}</option>\n      }\n    </select>\n  </label>\n  <div class=\"paginador-acciones\">\n    <button\n      type=\"button\"\n      aria-label=\"Primera página\"\n      [disabled]=\"cargando() || actual() === 0\"\n      (click)=\"irA(0)\"\n    >\n      «\n    </button>\n    <button\n      type=\"button\"\n      [disabled]=\"cargando() || actual() === 0\"\n      (click)=\"irA(actual() - 1)\"\n    >\n      Anterior\n    </button>\n    <span aria-live=\"polite\"\n      >Página {{ actual() + 1 }} de {{ paginas() || 1 }}</span\n    >\n    <button\n      type=\"button\"\n      [disabled]=\"cargando() || actual() >= paginas() - 1\"\n      (click)=\"irA(actual() + 1)\"\n    >\n      Siguiente\n    </button>\n    <button\n      type=\"button\"\n      aria-label=\"Última página\"\n      [disabled]=\"cargando() || actual() >= paginas() - 1\"\n      (click)=\"irA(paginas() - 1)\"\n    >\n      »\n    </button>\n  </div>\n</nav>\n",
  styles:[],
})
export class Paginador<T> {
  readonly pagina = input(0);
  readonly tamanio = input(10);
  readonly totalElementos = input(0);
  readonly totalPaginas = input(0);
  readonly cargando = input(false);
  readonly registros = input<readonly T[] | null>(null);
  readonly cambioPagina = output<number>();
  readonly cambioTamanio = output<number>();
  private readonly paginaLocal = signal(0);
  private readonly tamanioLocal = signal(10);
  readonly filas = computed(() =>
    this.registros() !== null ? this.tamanioLocal() : this.tamanio(),
  );
  readonly total = computed(
    () => this.registros()?.length ?? this.totalElementos(),
  );
  readonly paginas = computed(() =>
    this.registros() !== null
      ? Math.ceil(this.total() / this.filas())
      : this.totalPaginas(),
  );
  readonly actual = computed(() =>
    Math.max(
      0,
      Math.min(
        this.registros() !== null ? this.paginaLocal() : this.pagina(),
        Math.max(this.paginas() - 1, 0),
      ),
    ),
  );
  readonly contenido = computed(() =>
    (this.registros() ?? []).slice(
      this.actual() * this.filas(),
      (this.actual() + 1) * this.filas(),
    ),
  );
  readonly hasta = computed(() =>
    Math.min((this.actual() + 1) * this.filas(), this.total()),
  );
  readonly desde = computed(() =>
    Math.min(this.actual() * this.filas() + 1, this.hasta()),
  );
  irA(pagina: number) {
    if (this.cargando() || pagina < 0 || pagina >= this.paginas()) return;
    if (this.registros() !== null) this.paginaLocal.set(pagina);
    else this.cambioPagina.emit(pagina);
  }
  cambiarTamanio(event: Event) {
    const tamanio = Number((event.target as HTMLSelectElement).value);
    if (this.cargando() || ![10, 20, 50, 100].includes(tamanio)) return;
    if (this.registros() !== null) {
      this.tamanioLocal.set(tamanio);
      this.paginaLocal.set(0);
    } else this.cambioTamanio.emit(tamanio);
  }
}

