export class LoginComponent {
  private readonly changeDetector = inject(ChangeDetectorRef);

  auth = inject(AuthService);
  router = inject(Router);
  route = inject(ActivatedRoute, { optional: true });
  aviso =
    this.route?.snapshot.queryParamMap.get("sesionExpirada") === "1"
      ? "Tu sesión ha vencido. Inicia sesión nuevamente."
      : "";
  mostrar = false;
  error = "";
  loading = false;
  readonly loginForm = new FormGroup({
    username: new FormControl("", {
      nonNullable: true,
      validators: [Validators.required],
    }),
    password: new FormControl("", {
      nonNullable: true,
      validators: [Validators.required],
    }),
  });
  async login() {
    try {
      if (this.loading) return;
      if (this.loginForm.invalid) {
        this.loginForm.markAllAsTouched();
        this.error = "Introduce tu usuario y contraseña";
        return;
      }
      this.error = "";
      this.loading = true;
      try {
        const { username, password } = this.loginForm.getRawValue();
        const s = await this.auth.login(username, password);
        const destino = returnUrlSeguro(
          this.route?.snapshot.queryParamMap.get("returnUrl"),
        );
        const destinoMedico =
          destino &&
          /^\/doctor(?:\/(?:horarios|consultas))?(?:[?#]|$)/.test(destino)
            ? destino
            : "/doctor";
        await this.router.navigateByUrl(
          s.rol === "DOCTOR"
            ? destinoMedico
            : (destino ?? INICIO_POR_ROL[s.rol]),
        );
      } catch (e) {
        this.error = errorText(e);
      } finally {
        this.loading = false;
      }
    } finally {
      this.changeDetector.markForCheck();
    }
  }
}

export function returnUrlSeguro(value: unknown): string | null {
  if (
    typeof value !== "string" ||
    !value.startsWith("/") ||
    value.startsWith("//")
  )
    return null;
  let decoded: string;
  try {
    decoded = decodeURIComponent(value);
  } catch {
    return null;
  }
  if (
    decoded.startsWith("//") ||
    /[\\\u0000-\u0020\u007f]/.test(decoded) ||
    /^\/login(?:[/?#;]|$)/i.test(decoded)
  )
    return null;
  return value;
}

import { inject } from "@angular/core";
import { CanActivateFn, Router } from "@angular/router";
import { AuthService } from "../auth/auth-service";
import { returnUrlSeguro } from "../utils/return-url";
export const authGuard: CanActivateFn = (_route, state) => {
  if (inject(AuthService).estaAutenticado()) return true;
  const destino = returnUrlSeguro(state?.url);
  return inject(Router).parseUrl(
    destino ? "/login?returnUrl=" + encodeURIComponent(destino) : "/login",
  );
};

import { inject } from "@angular/core";
import { CanActivateFn, Router } from "@angular/router";
import { AuthService } from "../auth/auth-service";
import { Permiso } from "../auth/auth.model";
import { authGuard } from "./auth-guard";
export const permisoGuard: CanActivateFn = (route, state) => {
  const auth = inject(AuthService);
  if (!auth.estaAutenticado()) return authGuard(route, state);
  if (auth.session()?.rol === "DOCTOR" && route.data["redireccionDoctor"])
    return inject(Router).parseUrl(route.data["redireccionDoctor"]);
  if (
    auth.session()?.rol === "ADMINISTRADORA" &&
    route.data["redireccionAdmin"]
  )
    return inject(Router).parseUrl(route.data["redireccionAdmin"]);
  const permiso = route.data["permiso"] as Permiso | undefined;
  return permiso && auth.tienePermiso(permiso)
    ? true
    : inject(Router).parseUrl("/acceso-denegado");
};

